#define WIN32_LEAN_AND_MEAN
#define NOMINMAX
#include <windows.h>
#include "ascii_core.hpp"
#include <algorithm>
#include <cmath>
#include <cstring>
#include <fstream>
#include <iostream>
#include <limits>
#include <stdexcept>
using namespace asciifx;
int checks=0;void check(bool v,const char* why){++checks;if(!v)throw std::runtime_error(why);}
Image solid(int w,int h,float v,float a=1){Image s{w,h,0,0,std::vector<float>(std::size_t(w)*h*4)};for(std::size_t i=0;i<s.rgba.size();i+=4){s.rgba[i]=s.rgba[i+1]=s.rgba[i+2]=v;s.rgba[i+3]=a;}return s;}
bool same(const Image& a,const Image& b){return a.rgba.size()==b.rgba.size()&&!std::memcmp(a.rgba.data(),b.rgba.data(),a.rgba.size()*sizeof(float));}
double mean(const Image& a){double total=0;for(std::size_t i=0;i<a.rgba.size();i+=4)total+=a.rgba[i];return total/(a.width*a.height);}
GlyphAtlas fixture(){GlyphAtlas a;a.family="test geometry";for(int i=0;i<4;i++){std::vector<float> m(16);for(int j=0;j<16;j++)m[j]=i==3?1:i==2?((j/4)==1||(j%4)==1):i==1?(j==5):0;Glyph g;g.character=" .+#"[i];g.assign(4,4,m);a.glyphs.push_back(std::move(g));}a.normalize();return a;}
int main(int argc,char** argv){try{
 auto atlas=fixture();check(atlas.valid(),"test atlas");check(std::abs(atlas.glyphs.back().area(0,0,1,1)-1)<1e-9,"integral full area");check(std::abs(atlas.glyphs.back().area(.2,.3,.7,.8)-.25)<1e-9,"fractional integral");
 Parameters p;p.contrast=100;p.gamma=1;p.fill=100;p.ink={1,1,1};p.paper={0,0,0};p.cell_width=8;p.cell_aspect=1;
 auto input=solid(128,128,.7f);Image out,first;
 for(int dither=0;dither<3;dither++){p.dither=dither;p.dither_amount=100;check(render(input,p,atlas,out),"dither mode");if(dither)check(std::abs(mean(out)-.7)<.035,"nonuniform glyph-density quantization conserves tone");}
 p.dither=0;p.dither_amount=0;check(render(input,p,atlas,first),"no dither");p.dither=1;check(render(input,p,atlas,out)&&same(out,first),"zero ordered amount is none");p.dither=2;check(render(input,p,atlas,out)&&same(out,first),"zero diffusion amount is none");
 p.mix=0;input.rgba[0]=4.5f;check(render(input,p,atlas,out)&&same(input,out),"zero mix exact HDR bypass");
 input=solid(65,47,.5f,.6f);p={};p.background=1;p.dither=0;p.ink={.2,.8,.4};check(render(input,p,atlas,out),"transparent characters");for(std::size_t i=0;i<out.rgba.size();i+=4){check(out.rgba[i+3]>=0&&out.rgba[i+3]<=.600001,"no alpha expansion");if(out.rgba[i+3]>0)for(int k=0;k<3;k++)check(std::abs(out.rgba[i+k]-p.ink[k])<1e-5,"straight-alpha ink colour");}
 auto ink=out;p.mix=37;check(render(input,p,atlas,out),"partial mix");for(std::size_t i=0;i<out.rgba.size();i+=4){double a=input.rgba[i+3]*.63+ink.rgba[i+3]*.37;check(std::abs(out.rgba[i+3]-a)<1e-6,"mixed alpha");for(int k=0;k<3;k++)check(std::abs(out.rgba[i+k]-(input.rgba[i+k]*input.rgba[i+3]*.63+ink.rgba[i+k]*ink.rgba[i+3]*.37)/a)<1e-5,"premultiplied mix");}
 auto hdr=solid(32,32,0);for(std::size_t i=0;i<hdr.rgba.size();i+=4){hdr.rgba[i]=1e20f;hdr.rgba[i+1]=1e19f;}p={};p.color_mode=1;p.background=1;check(render(hdr,p,atlas,out),"HDR source hue");for(std::size_t i=0;i<out.rgba.size();i+=4)if(out.rgba[i+3]>0)check(std::abs(out.rgba[i]-.1*out.rgba[i+1]*100)<1e-5,"HDR channel ratio preserved");
 p={};p.dither=1;check(render(input,p,atlas,first),"grid origin");input.left=-19;input.top=37;p.shift_x=-19;p.shift_y=37;check(render(input,p,atlas,out)&&same(first,out),"document anchoring");
 auto hidden=input;for(std::size_t i=0;i<hidden.rgba.size();i+=4)if(i%7==0){hidden.rgba[i+3]=0;for(int k=0;k<3;k++)hidden.rgba[i+k]=999;}
 auto clean=hidden;for(std::size_t i=0;i<clean.rgba.size();i+=4)if(clean.rgba[i+3]==0)for(int k=0;k<3;k++)clean.rgba[i+k]=0;
 check(render(hidden,p,atlas,first)&&render(clean,p,atlas,out)&&same(first,out),"hidden RGB does not stain cell averages");
 for(auto size:{std::pair{1,1},std::pair{1,19},std::pair{31,1},std::pair{65,47}}){auto a=solid(size.first,size.second,.4f);p={};p.cell_width=8.7;p.shift_x=-13.1;p.shift_y=4.25;check(render(a,p,atlas,out)&&out.valid(),"fractional/tiny cell intersections");}
 auto medium=solid(513,257,.5f);p={};p.cell_width=.25;check(render(medium,p,atlas,out),"minified glyph averaging");
 p={};auto invalid=p;invalid.cell_width=0;check(!valid(invalid)&&!render(medium,invalid,atlas,out),"invalid width rejected");GlyphAtlas empty;check(!render(medium,p,empty,out),"empty glyph library rejected");
 auto nan=input;nan.rgba[0]=std::numeric_limits<float>::quiet_NaN();nan.rgba[3]=std::numeric_limits<float>::infinity();check(render(nan,p,atlas,out),"nonfinite source");for(float x:out.rgba)check(std::isfinite(x),"finite output");
 auto sentinel=solid(2,2,.3f);out=sentinel;int polls=0;check(!render(medium,p,atlas,out,[&]{return ++polls>4;})&&same(out,sentinel),"cancel does not publish partial pixels");
 // Actual installed Windows typefaces, all sets and both weights. No font file
 // is distributed or generated by the test.
 for(int font=0;font<3;font++)for(int set=0;set<4;set++)for(bool bold:{false,true}){p={};p.font=font;p.charset=set;p.bold=bold;auto a=make_atlas(p);check(a.valid()&&!a.family.empty(),"installed system glyphs");for(std::size_t i=1;i<a.glyphs.size();i++)check(a.glyphs[i].density>=a.glyphs[i-1].density,"actual ink density order");}
 p={};auto warm=make_atlas(p);check(warm.valid(),"GDI warm");auto before=GetGuiResources(GetCurrentProcess(),GR_GDIOBJECTS);
 for(int i=0;i<8;i++){int count=0;auto a=make_atlas(p,[&]{return ++count>3;});check(!a.valid(),"font build cancellation");}
 check(GetGuiResources(GetCurrentProcess(),GR_GDIOBJECTS)==before,"font/bitmap/DC handles released after cancellation");
 std::ofstream raw(argc>1?argv[1]:"ascii-deterministic.f32",std::ios::binary);
 for(int i=0;i<6;i++){p=preset(i);check(valid(p),"preset valid");auto a=make_atlas(p);for(std::size_t n=0;n<medium.rgba.size();n+=4){medium.rgba[n]=float((n*7)%129)/128;medium.rgba[n+1]=float((n*13)%113)/112;medium.rgba[n+2]=float((n*3)%97)/96;medium.rgba[n+3]=float((n*11)%31)/30;}check(render(medium,p,a,out),"deterministic full output");raw.write(reinterpret_cast<const char*>(out.rgba.data()),std::streamsize(out.rgba.size()*sizeof(float)));}
 check(raw.good(),"fixture write");std::cout<<"PASS: "<<checks<<" assertions; glyph integrals, installed fonts, tone conservation, ordered/diffusion dithering, colour/alpha, tiny/fractional grids, coordinates, cancellation and GDI resource ownership.\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
